import { keyBy } from 'es-toolkit/array';
import { sumBy } from 'es-toolkit/math';
import { isEmpty } from 'es-toolkit/compat';

export interface Row { id: number; name: string; age: number; }
export type Config = Record<string, unknown>;

export function byId(rows: Row[]): Record<string, Row> {
  return keyBy(rows, (row) => String(row.id));
}
export function totalAge(rows: Row[]): number {
  return sumBy(rows, (row) => row.age);
}
export function isBlank(value: unknown): boolean {
  return isEmpty(value);
}
```

**Choices:**
- **`byId`**: `keyBy` from `es-toolkit/array`. Keying by `String(row.id)` is a small adapter so the result is `Record<string, Row>` and type-checks. Last duplicate wins, as in lodash.
- **`totalAge`**: `sumBy` from `es-toolkit/math`. The lodash string shorthand `'age'` became an arrow function, which is the only call-shape adapter. Empty input returns 0.
- **`isBlank`**: es-toolkit has no top-level `isEmpty`. Its `isEmptyObject` returns false for `null`, strings and arrays, so it doesn't match. I used `isEmpty` from `es-toolkit/compat`, which is the library's lodash-compatible version and needs no hand-written logic.
- **Lodash import**: none kept, since every function has an es-toolkit equivalent.

